PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('SUPER_ADMIN','HOSPITAL_ADMIN','DOCTOR','RECEPTIONIST','NURSE','LAB_TECHNICIAN','PHARMACIST','ACCOUNTANT')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, phone TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS doctors (id TEXT PRIMARY KEY, user_id TEXT UNIQUE REFERENCES users(id), name TEXT NOT NULL, email TEXT UNIQUE, phone TEXT, specialty TEXT NOT NULL, qualification TEXT, experience_years INTEGER NOT NULL DEFAULT 0, consultation_fee INTEGER NOT NULL DEFAULT 0, department_id TEXT NOT NULL REFERENCES departments(id), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, patient_number TEXT NOT NULL UNIQUE, uhid TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, date_of_birth TEXT, gender TEXT NOT NULL, blood_group TEXT, phone TEXT NOT NULL, email TEXT, address TEXT, emergency_name TEXT, emergency_phone TEXT, allergies TEXT, medical_history TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', doctor_id TEXT REFERENCES doctors(id), department_id TEXT REFERENCES departments(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS patients_name_idx ON patients(first_name,last_name);
CREATE INDEX IF NOT EXISTS patients_phone_idx ON patients(phone);
CREATE TABLE IF NOT EXISTS doctor_schedules (id TEXT PRIMARY KEY, doctor_id TEXT NOT NULL REFERENCES doctors(id) ON DELETE CASCADE, day_of_week INTEGER NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, slot_minutes INTEGER NOT NULL DEFAULT 30, active INTEGER NOT NULL DEFAULT 1, UNIQUE(doctor_id,day_of_week,start_time));
CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY, appointment_number TEXT NOT NULL UNIQUE, patient_id TEXT NOT NULL REFERENCES patients(id), doctor_id TEXT NOT NULL REFERENCES doctors(id), department_id TEXT NOT NULL REFERENCES departments(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'CONSULTATION', status TEXT NOT NULL DEFAULT 'SCHEDULED', notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS appointments_doctor_time_idx ON appointments(doctor_id,starts_at,ends_at);
CREATE INDEX IF NOT EXISTS appointments_patient_time_idx ON appointments(patient_id,starts_at);
CREATE TABLE IF NOT EXISTS consultations (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), doctor_id TEXT NOT NULL REFERENCES doctors(id), appointment_id TEXT UNIQUE REFERENCES appointments(id), diagnosis TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS medical_history (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE, title TEXT NOT NULL, details TEXT NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vitals (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), entered_by_id TEXT NOT NULL REFERENCES users(id), systolic INTEGER, diastolic INTEGER, heart_rate INTEGER, oxygen REAL, temperature REAL, weight REAL, height REAL, bmi REAL, notes TEXT, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS vitals_patient_date_idx ON vitals(patient_id,recorded_at);
CREATE TABLE IF NOT EXISTS medicines (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, minimum_stock INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS medicines_name_idx ON medicines(name);
CREATE TABLE IF NOT EXISTS medicine_batches (id TEXT PRIMARY KEY, medicine_id TEXT NOT NULL REFERENCES medicines(id) ON DELETE CASCADE, batch_number TEXT NOT NULL, expiry_date TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), purchase_price INTEGER NOT NULL, selling_price INTEGER NOT NULL, UNIQUE(medicine_id,batch_number));
CREATE TABLE IF NOT EXISTS stock_transactions (id TEXT PRIMARY KEY, medicine_id TEXT NOT NULL REFERENCES medicines(id), batch_id TEXT REFERENCES medicine_batches(id), quantity INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, email TEXT);
CREATE TABLE IF NOT EXISTS purchase_orders (id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), status TEXT NOT NULL DEFAULT 'RECEIVED', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS prescriptions (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), doctor_id TEXT NOT NULL REFERENCES doctors(id), authorized_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS prescription_items (id TEXT PRIMARY KEY, prescription_id TEXT NOT NULL REFERENCES prescriptions(id) ON DELETE CASCADE, medicine_id TEXT NOT NULL REFERENCES medicines(id), dosage TEXT NOT NULL, duration TEXT NOT NULL, quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lab_orders (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), status TEXT NOT NULL DEFAULT 'ORDERED', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lab_order_items (id TEXT PRIMARY KEY, lab_order_id TEXT NOT NULL REFERENCES lab_orders(id) ON DELETE CASCADE, test_name TEXT NOT NULL, category TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ORDERED', technician_id TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS lab_results (id TEXT PRIMARY KEY, item_id TEXT NOT NULL UNIQUE REFERENCES lab_order_items(id), value TEXT NOT NULL, unit TEXT, reference_range TEXT, verified_at TEXT, published_at TEXT);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, invoice_number TEXT NOT NULL UNIQUE, patient_id TEXT NOT NULL REFERENCES patients(id), status TEXT NOT NULL DEFAULT 'PENDING', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoice_items (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price INTEGER NOT NULL, discount INTEGER NOT NULL DEFAULT 0, tax INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id), amount INTEGER NOT NULL CHECK(amount>0), method TEXT NOT NULL CHECK(method IN ('CASH','CARD','UPI','BANK_TRANSFER')), reference TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, type TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), name TEXT NOT NULL, storage_key TEXT NOT NULL, mime_type TEXT NOT NULL, uploaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_logs (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), patient_id TEXT REFERENCES patients(id), action TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS activity_date_idx ON activity_logs(created_at);
